; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 13: Input "How many numbers (Return = 2000)"; n
			dw kw_printstrvar, str0
			dw kw_inputint, var_n

			; main.bas 14: If n < 10 Or n > MAXN Then n = MAXN
			dw kw_scpltvl, var_n, 10
			dw kw_ftov, tmp0
			dw kw_scpgtvl, var_n, 2000
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if1_1
			dw kw_ltov, 2000, var_n
if1_1:

			; main.bas 15: Do
do2_t:

			; main.bas 16: Print
			dw kw_printnl

			; main.bas 17: Print "T = turbo, N = normal, X = exit"
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 18: Do : k = UCase$(Inkey$) : Frame : Loop Until (k = "T") Or (k = "N") Or (k = "X")
do3_t:
			dw kw_inkeys, stmp0
			dw kw_strucase, stmp0, stmp0
			dw kw_strcpy, var_k, stmp0
			dw kw_frame
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_strcmpeq, var_k, str4
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, do3_t
do3_e:

			; main.bas 19: If k = "X" Then Exit Do
			dw kw_strcmpeq, var_k, str4
			dw kw_goto_iffalse_n, if4_1
			dw do2_e_go
if4_1:

			; main.bas 21: Randomize 7
			dw kw_seedl, 7

			; main.bas 22: For i = 0 To n
			dw kw_ztov, var_i
			dw kw_vtov, var_n, for5_l
			dw kw_forupv_n, var_i, for5_l, for5_e
for5_t:

			; main.bas 23: a(i) = Rnd(1000)
			dw kw_rndl, 1000, tmp1
			dw kw_aset, arr_a, var_i, tmp1

			; main.bas 24: Next
			dw kw_next1v_n, var_i, for5_l, for5_t
for5_e:

			; main.bas 25: Print IIf(k = "T", "Turbo", "Normal"); ": sorting "; n + 1; " numbers..."
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, ch6_0
			dw kw_strcpy, stmp0, str5
			dw ch6_e_go
ch6_0:
			dw kw_strcpy, stmp0, str6
			dw ch6_e_go
ch6_1:
			dw kw_strcpy, stmp0, str7
ch6_e:
			dw kw_printstrvar, stmp0
			dw kw_addl, var_n, 1, tmp0
			dw kw_printstrvar, str8
			dw kw_printint, tmp0
			dw kw_printstrvar, str9
			dw kw_printnl

			; main.bas 26: t0 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t0

			; main.bas 27: If k = "T" Then
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, if7_1

			; main.bas 28: Turbo On
			dw kw_turbo_on

			; main.bas 29: ShellSort
			dw p_shellsort_c

			; main.bas 30: Turbo Off
			dw kw_turbo_off

			; main.bas 31: Else
			dw if7_e_go
if7_1:

			; main.bas 32: ShellSort
			dw p_shellsort_n_c

			; main.bas 33: End If
if7_e:

			; main.bas 34: t1 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t1

			; main.bas 35: Print "Done - stop the stopwatch"
			dw kw_printstrvar, str10
			dw kw_printnl

			; main.bas 36: For i = 0 To 9
			dw kw_ztov, var_i
for8_t:

			; main.bas 37: Print a(i); " ";
			dw kw_aget, arr_a, var_i, tmp0
			dw kw_printint, tmp0
			dw kw_printstrvar, str11

			; main.bas 38: Next
			dw kw_next1l_n, var_i, 9, for8_t
for8_e:

			; main.bas 39: Print
			dw kw_printnl

			; main.bas 40: If (k = "N") And (System.TicksPerSecond > 0) Then
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, if9_1

			; main.bas 41: Print "took "; t1 - t0; " ticks = "; (t1 - t0) \ System.TicksPerSecond; "."; ((t1 - t0) Mod System.TicksPerSecond) * 10 \ System.TicksPerSecond; " s"
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_printstrvar, str12
			dw kw_printint, tmp0
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_divvl, tmp0, 300, tmp0
			dw kw_printstrvar, str13
			dw kw_printint, tmp0
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_modvl, tmp0, 300, tmp0
			dw kw_mulvl, tmp0, 10, tmp0
			dw kw_divvl, tmp0, 300, tmp0
			dw kw_printstrvar, str14
			dw kw_printint, tmp0
			dw kw_printstrvar, str15
			dw kw_printnl

			; main.bas 42: ElseIf k = "T" Then
			dw do2_t_go
if9_1:
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, do2_t

			; main.bas 43: Print "(turbo runs with interrupts off, so"
			dw kw_printstrvar, str16
			dw kw_printnl

			; main.bas 44: Print "time it with the stopwatch)"
			dw kw_printstrvar, str17
			dw kw_printnl

			; main.bas 45: End If
if9_2:
if9_e:

			; main.bas 46: Loop
			dw do2_t_go
do2_e:

			; main.bas 47: End
			dw kw_stop

; ============================================================
; sub shellsort (turbo mode)
; ============================================================

p_shellsort:

			; main.bas 50: Dim gap As Integer, i As Integer, j As Integer, t As Integer

			; main.bas 51: gap = n \ 2
			dw kw_divvl, var_n, 2, var_shellsort_gap

			; main.bas 52: Do While gap > 0
do10_t:
			dw kw_scpgtvl, var_shellsort_gap, 0
			dw kw_goto_iffalse, do10_e

			; main.bas 53: For i = gap To n
			dw kw_vtov, var_shellsort_gap, var_shellsort_i
			dw kw_vtov, var_n, for11_l
			dw kw_forupv, var_shellsort_i, for11_l, for11_e
for11_t:

			; main.bas 54: t = a(i)
			dw kw_aget, arr_a, var_shellsort_i, var_shellsort_t

			; main.bas 55: j = i
			dw kw_vtov, var_shellsort_i, var_shellsort_j

			; main.bas 56: Do While j >= gap
do12_t:
			dw kw_scpgevv, var_shellsort_j, var_shellsort_gap
			dw kw_goto_iffalse, do12_e

			; main.bas 57: If a(j - gap) <= t Then Exit Do
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp0
			dw kw_aget, arr_a, tmp0, tmp0
			dw kw_scplevv, tmp0, var_shellsort_t
			dw kw_goto_iffalse, if13_1
			dw do12_e_go
if13_1:

			; main.bas 58: a(j) = a(j - gap)
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp1
			dw kw_aget, arr_a, tmp1, tmp1
			dw kw_aset, arr_a, var_shellsort_j, tmp1

			; main.bas 59: j = j - gap
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, var_shellsort_j

			; main.bas 60: Loop
			dw do12_t_go
do12_e:

			; main.bas 61: a(j) = t
			dw kw_aset, arr_a, var_shellsort_j, var_shellsort_t

			; main.bas 62: Next
			dw kw_next1v, var_shellsort_i, for11_l, for11_t
for11_e:

			; main.bas 63: gap = gap \ 2
			dw kw_divvl, var_shellsort_gap, 2, var_shellsort_gap

			; main.bas 64: Loop
			dw do10_t_go
do10_e:
			dw p_shellsort_r

; ============================================================
; sub shellsort (normal mode)
; ============================================================

p_shellsort_n:

			; main.bas 50: Dim gap As Integer, i As Integer, j As Integer, t As Integer

			; main.bas 51: gap = n \ 2
			dw kw_divvl, var_n, 2, var_shellsort_gap

			; main.bas 52: Do While gap > 0
do14_t:
			dw kw_scpgtvl, var_shellsort_gap, 0
			dw kw_goto_iffalse_n, do14_e

			; main.bas 53: For i = gap To n
			dw kw_vtov, var_shellsort_gap, var_shellsort_i
			dw kw_vtov, var_n, for15_l
			dw kw_forupv_n, var_shellsort_i, for15_l, for15_e
for15_t:

			; main.bas 54: t = a(i)
			dw kw_aget, arr_a, var_shellsort_i, var_shellsort_t

			; main.bas 55: j = i
			dw kw_vtov, var_shellsort_i, var_shellsort_j

			; main.bas 56: Do While j >= gap
do16_t:
			dw kw_scpgevv, var_shellsort_j, var_shellsort_gap
			dw kw_goto_iffalse_n, do16_e

			; main.bas 57: If a(j - gap) <= t Then Exit Do
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp0
			dw kw_aget, arr_a, tmp0, tmp0
			dw kw_scplevv, tmp0, var_shellsort_t
			dw kw_goto_iffalse_n, if17_1
			dw do16_e_go
if17_1:

			; main.bas 58: a(j) = a(j - gap)
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp1
			dw kw_aget, arr_a, tmp1, tmp1
			dw kw_aset, arr_a, var_shellsort_j, tmp1

			; main.bas 59: j = j - gap
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, var_shellsort_j

			; main.bas 60: Loop
			dw do16_t_go
do16_e:

			; main.bas 61: a(j) = t
			dw kw_aset, arr_a, var_shellsort_j, var_shellsort_t

			; main.bas 62: Next
			dw kw_next1v_n, var_shellsort_i, for15_l, for15_t
for15_e:

			; main.bas 63: gap = gap \ 2
			dw kw_divvl, var_shellsort_gap, 2, var_shellsort_gap

			; main.bas 64: Loop
			dw do14_t_go
do14_e:
			dw p_shellsort_n_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_e_go:			ld sp, do2_e
			jp ntc_xn
ch6_e_go:			ld sp, ch6_e
			jp ntc_xn
if7_e_go:			ld sp, if7_e
			jp ntc_xn
do2_t_go:			ld sp, do2_t
			jp ntc_xn
do12_e_go:			ld sp, do12_e
			ret
do12_t_go:			ld sp, do12_t
			ret
do10_t_go:			ld sp, do10_t
			ret
do16_e_go:			ld sp, do16_e
			jp ntc_xn
do16_t_go:			ld sp, do16_t
			jp ntc_xn
do14_t_go:			ld sp, do14_t
			jp ntc_xn

p_shellsort_c:		; call shellsort (turbo)
			ld hl, 0
			ld (var_shellsort_gap), hl
			ld hl, 0
			ld (var_shellsort_i), hl
			ld hl, 0
			ld (var_shellsort_j), hl
			ld hl, 0
			ld (var_shellsort_t), hl
			ld (p_shellsort_rs), sp
			ld sp, p_shellsort
			ret
p_shellsort_r:		; end of shellsort
			ld sp, (p_shellsort_rs)
			ret
p_shellsort_n_c:		; call shellsort (normal)
			ld hl, 0
			ld (var_shellsort_gap), hl
			ld hl, 0
			ld (var_shellsort_i), hl
			ld hl, 0
			ld (var_shellsort_j), hl
			ld hl, 0
			ld (var_shellsort_t), hl
			ld (p_shellsort_rs), sp
			ld sp, p_shellsort_n
			jp ntc_xn
p_shellsort_n_r:		; end of shellsort
			ld sp, (p_shellsort_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
			db 40			; capacity
var_k:			ds 41
var_i:			dw 0
for5_l:			dw 0
var_t0:			dw 0
var_t1:			dw 0
p_shellsort_rs:			dw 0
var_shellsort_gap:			dw 0
var_shellsort_i:			dw 0
var_shellsort_j:			dw 0
var_shellsort_t:			dw 0
for11_l:			dw 0
for15_l:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 255			; capacity
stmp0:			ds 256

; ============================================================
; Strings
; ============================================================

str0:			db "How many numbers (Return = 2000)? ", 0
str1:			db "T = turbo, N = normal, X = exit", 0
str2:			db "T", 0
str3:			db "N", 0
str4:			db "X", 0
str5:			db "Turbo", 0
str6:			db "Normal", 0
str7:			db 0
str8:			db ": sorting ", 0
str9:			db " numbers...", 0
str10:			db "Done - stop the stopwatch", 0
str11:			db " ", 0
str12:			db "took ", 0
str13:			db " ticks = ", 0
str14:			db ".", 0
str15:			db " s", 0
str16:			db "(turbo runs with interrupts off, so", 0
str17:			db "time it with the stopwatch)", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the NTC LIBRARY ROM (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_turbo_on:	jp 5
kw_turbo_off:	jp 7
kw_goto_iffalse:	jp 10
kw_goto_iffalse_n:	jp 11
kw_goto_ifzero_n:	jp 15
kw_forupv:	jp 24
kw_forupv_n:	jp 25
kw_next1l_n:	jp 31
kw_next1v:	jp 32
kw_next1v_n:	jp 33
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_addl:		jp 54
kw_subvv:	jp 55
kw_mulvl:	jp 61
kw_divvl:	jp 64
kw_modvl:	jp 67
kw_orvv:		jp 74
kw_scpltvl:	jp 80
kw_scplevv:	jp 81
kw_scpgtvl:	jp 84
kw_scpgevv:	jp 85
kw_aget:		jp 111
kw_aset:		jp 112
kw_rndl:		jp 119
kw_seedl:	jp 121
kw_strcpy:	jp 122
kw_strcmpeq:	jp 126
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl:	jp 138
kw_inputint:	jp 142
kw_inkeys:	jp 145
kw_frame:	jp 152
kw_ticks:	jp 154
kw_strucase:	jp 180
kw_bssinit:	jp 288
NTC_RJ_N	equ 41		; entries
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8806		; ROM data
ntc_v_free	equ #8844		; ROM data
ntc_v_romen	equ #884A		; ROM data
ntc_v_romold	equ #884C		; ROM data
ntc_v_stamp	equ #8848		; ROM data
ntc_v_start	equ #8846		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPCFW", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "NTC LIBRARY ROM (CPCFW) not found", 0
ntc_rj_tlk:		db "NTC LIBRARY ROM too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_a		equ ntc_bss + 0		; 4002 bytes
ntc_bss_size	equ 4002
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "E26.BIN", ntc_start, ntc_end - ntc_start, ntc_start